commands.command:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -NoProfile -Command '$record = Get-Content -LiteralPath task.json -Raw | ConvertFrom-Json
$means = @($record.baseline, $record.candidate) | ForEach-Object { $values = @($_.latencies_ms | ForEach-Object { ($_ | Measure-Object -Average).Average }); $sorted = @($values | Sort-Object); [pscustomobject]@{trial_means_ms=$values; median_ms=$sorted[2]; relative_spread_pct=100*($sorted[-1]-$sorted[0])/$sorted[2]} }
[pscustomobject]@{baseline=$means[0]; candidate=$means[1]; latency_reduction_pct=100*(1-$means[1].median_ms/$means[0].median_ms)} | ConvertTo-Json -Depth 4'
